new:
pub(crate) fn routing_policy_summary(&self) -> String {
    if !self.routing_enabled {
        return "single-model benchmark baseline; routing and fallback disabled".to_owned();
    }
    format!(
        "{} adopted specialist workload(s)",
        self.routing.adopted_specialist_count()
    )
}
pub(crate) fn model_turns(&self) -> u64 {
    u64::from(self.turns)
}
pub(crate) fn tool_failures(&self) -> u64 {
    u64::from(self.failures)
}
pub(crate) fn is_single_model_baseline(&self) -> bool {
    !self.routing_enabled
}
